-- Recover book-project state from verified title evidence without altering publication.
update public.command_center_project_profiles set status='Production complete / publication unconfirmed',stage='Final production package complete; Kindle and paperback upload files prepared. Current publication is not confirmed.',next_action='Resume platform-side verification using the current final upload package; do not infer publication from production completion.',progress_summary='Production complete',status_observed_at='2026-10-05T00:00:00Z',status_source_refs=array['library:libfile_9ddd9ccb50ec81918fb45da013a0fc54','library:libfile_1ca351989854819199602a5ce76ff11d'],version=version+1,updated_at=now() where project_id='kdp-weight-between-tasks' and stage is null;
update public.command_center_project_profiles p set status='Book catalogue / publication tracking',stage=(select count(*)::text||' saved titles; production and publication tracked separately' from public.command_center_book_catalogue b where b.owner_id=p.owner_id),next_action='Open the book catalogue and resume each title from its recorded production and format-specific publication state.',status_observed_at=now(),status_source_refs=array['supabase:command_center_book_catalogue'],version=version+1,updated_at=now() where project_id='kdp' and stage is null;